transforms.code:
from java.lang import Throwable
try:
	j = int(self.view.custom.jog)
except Throwable:
	j = 0
try:
	cur = float(system.tag.readBlocking(["[MachineDemo]Robot/Lift_mm"])[0].value)
except Throwable:
	return ""
try:
	tgt = float(self.view.custom.liftTarget)
except Throwable:
	tgt = cur
nxt = cur
if j != 0:
	nxt = cur + (j * 16.0)
	if nxt < 0.0:
		nxt = 0.0
	if nxt > 1200.0:
		nxt = 1200.0
	self.view.custom.liftTarget = nxt
elif self.view.custom.seek:
	d = tgt - cur
	if abs(d) <= 26.0:
		nxt = tgt
		self.view.custom.seek = False
	elif d > 0:
		nxt = cur + 26.0
	else:
		nxt = cur - 26.0
else:
	return ""
try:
	system.tag.writeBlocking(["[MachineDemo]Robot/Lift_mm"], [nxt])
except Throwable:
	pass
return ""

